SELECT (SELECT rootpage FROM sqlite_schema WHERE type='table' AND name='t2') AS t2_root, count(*) AS physical_rows, sum(CASE WHEN typeof(a)='text' THEN 1 ELSE 0 END) AS text_rows, sum(CASE WHEN a='active' THEN 1 ELSE 0 END) AS active_rows, sum(CASE WHEN a='boomer' THEN 1 ELSE 0 END) AS boomer_rows, sum(CASE WHEN a='atom' THEN 1 ELSE 0 END) AS atom_rows, sum(CASE WHEN a='atomic' THEN 1 ELSE 0 END) AS atomic_rows, sum(CASE WHEN a='alpha channel backup abandon test aback boomer atom alpha active' THEN 1 ELSE 0 END) AS long_rows FROM t2;